from __future__ import annotations

from typing import Any


class AnalyticsClient:
    def __init__(self) -> None:
        self._responses: dict[str, dict[str, Any]] = {}
        self._calls = 0

    def seed(self, responses: dict[str, dict[str, Any]]) -> None:
        self._responses = {str(key): dict(value) for key, value in responses.items()}
        self._calls = 0

    def fetch(self, query_key: str) -> dict[str, Any]:
        key = query_key.strip().lower()
        if not key:
            return {"ok": False, "reason": "invalid_query"}
        self._calls += 1
        payload = self._responses.get(key)
        if payload is None:
            return {"ok": False, "reason": "not_found", "query_key": key}
        return {
            "ok": True,
            "query_key": key,
            "score": int(payload.get("score", 0)),
            "segment": str(payload.get("segment", "unknown")).strip().lower(),
        }

    def call_count(self) -> int:
        return self._calls

    def clear_calls(self) -> None:
        self._calls = 0

    def has_query(self, query_key: str) -> bool:
        return query_key.strip().lower() in self._responses

    def snapshot(self) -> dict[str, Any]:
        return {"responses": dict(self._responses), "calls": self._calls}

    def remove_query(self, query_key: str) -> bool:
        key = query_key.strip().lower()
        if not key:
            return False
        if key in self._responses:
            del self._responses[key]
            return True
        return False

    def response_count(self) -> int:
        return len(self._responses)

