from __future__ import annotations

from typing import Any

from analytics_client import AnalyticsClient


_CACHE: dict[str, dict[str, Any]] = {}


def get_analytics(query: dict[str, Any], client: AnalyticsClient) -> dict[str, Any]:
    account_id = str(query.get("account_id", "")).strip().lower()
    metric = str(query.get("metric", "")).strip().lower()
    window = str(query.get("window", "7d")).strip().lower()

    if not account_id:
        return {"ok": False, "reason": "invalid_account_id"}
    if not metric:
        return {"ok": False, "reason": "invalid_metric"}
    if window not in {"1d", "7d", "30d"}:
        return {"ok": False, "reason": "invalid_window"}

    query_key = f"{account_id}:{metric}:{window}"

    # Bug: cache is ignored and upstream is called every time.
    payload = client.fetch(query_key)
    if not payload.get("ok"):
        return {"ok": False, "reason": payload.get("reason", "upstream_error")}

    _CACHE[query_key] = dict(payload)
    return {"ok": True, "reason": "ok", "data": payload}


def clear_cache() -> None:
    _CACHE.clear()


def cache_size() -> int:
    return len(_CACHE)


def cache_keys() -> list[str]:
    return sorted(_CACHE.keys())


def has_cache_key(key: str) -> bool:
    return key in _CACHE


def cache_snapshot() -> dict[str, dict[str, Any]]:
    return {key: dict(value) for key, value in _CACHE.items()}

